import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Apps","description":"Explore the platform apps and first-party Sovereign apps included with the workspace runtime.","frontmatter":{"title":"Apps","description":"Explore the platform apps and first-party Sovereign apps included with the workspace runtime.","aside":false,"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/product/apps.md"},"headers":[],"relativePath":"product/apps.md","filePath":"product/apps.md"}'),s={name:"product/apps.md"};function o(i,e,p,l,d,c){return t(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="apps-in-a-sovereign-workspace" tabindex="-1">Apps in a Sovereign workspace <a class="header-anchor" href="#apps-in-a-sovereign-workspace" aria-label="Permalink to &quot;Apps in a Sovereign workspace&quot;">​</a></h1><p>Sovereign ships with the platform apps needed to operate a workspace and a growing set of first-party apps for everyday work. Operators decide which apps are enabled for their users, so availability can differ between instances.</p><p>In the user interface these are <strong>apps</strong>. In the repository and developer documentation they are delivered as <strong>plugins</strong>.</p><h2 id="first-party-sovereign-apps" tabindex="-1">First-party Sovereign apps <a class="header-anchor" href="#first-party-sovereign-apps" aria-label="Permalink to &quot;First-party Sovereign apps&quot;">​</a></h2><p>These are built and maintained by the Sovereign project and installed per instance. Availability below describes the app&#39;s own maturity, not whether any particular instance offers it — that stays the operator&#39;s decision.</p><h3 id="sovereign-kanban" tabindex="-1">Sovereign Kanban <a class="header-anchor" href="#sovereign-kanban" aria-label="Permalink to &quot;Sovereign Kanban&quot;">​</a></h3><p><strong>Status:</strong> Available</p><p>A minimalist alternative to Trello: projects, boards, lists, and cards, with drag-and-drop reordering that is also fully keyboard-accessible. Cards carry Markdown descriptions, labels, assignees, due dates, checklists, threaded comments, and an activity log. Boards are shared by invite with owner and member roles, archived rather than deleted, and readable in full — with editing hidden — by members of a public project.</p><p><a href="https://github.com/sovereignfs/sovereign-plugin-kanban" target="_blank" rel="noreferrer">Source: sovereign-plugin-kanban</a></p><h3 id="sovereign-ledger" tabindex="-1">Sovereign Ledger <a class="header-anchor" href="#sovereign-ledger" aria-label="Permalink to &quot;Sovereign Ledger&quot;">​</a></h3><p><strong>Status:</strong> Available</p><p>A budget-based personal finance tracker for a single user. Set up a budget once — currencies, income, fixed and dynamic expense categories, saving plans, and a balance sheet of accounts, cards, assets, deposits, loans, and people — then track spending against it. Includes month-end review, saving jars, rule-based insights, a daily exchange-rate job, and a month-end recap. Genuinely multi-currency.</p><p><a href="https://github.com/sovereignfs/sovereign-plugin-ledger" target="_blank" rel="noreferrer">Source: sovereign-plugin-ledger</a></p><h3 id="sovereign-plainwrite" tabindex="-1">Sovereign Plainwrite <a class="header-anchor" href="#sovereign-plainwrite" aria-label="Permalink to &quot;Sovereign Plainwrite&quot;">​</a></h3><p><strong>Status:</strong> Available</p><p>A Git-backed content editor for Markdown and MDX static sites. Plainwrite covers project membership, GitHub content sync, local drafts, structured frontmatter, and publishing flows. It demonstrates how an app can use platform identity, secrets, external connections, notifications, activity, portability, and data contracts while keeping its publishing workflow plugin-owned.</p><p><a href="https://github.com/sovereignfs/sovereign-plugin-plainwrite" target="_blank" rel="noreferrer">Source: sovereign-plugin-plainwrite</a></p><h3 id="sovereign-sheets" tabindex="-1">Sovereign Sheets <a class="header-anchor" href="#sovereign-sheets" aria-label="Permalink to &quot;Sovereign Sheets&quot;">​</a></h3><p><strong>Status:</strong> Available</p><p>A lightweight spreadsheet: a cell grid, a formula bar, and multiple sheet tabs per workbook. Alongside standard formulas it adds <code>FINANCE(base, quote)</code> for pulling a live currency rate into a cell. Workbooks can be shared with other users on the instance as owner, editor, or viewer, and exported to CSV or to a native JSON file that round-trips formulas, formatting, validation rules, and named ranges.</p><p><a href="https://github.com/sovereignfs/sovereign-plugin-sheets" target="_blank" rel="noreferrer">Source: sovereign-plugin-sheets</a></p><h3 id="sovereign-shopper" tabindex="-1">Sovereign Shopper <a class="header-anchor" href="#sovereign-shopper" aria-label="Permalink to &quot;Sovereign Shopper&quot;">​</a></h3><p><strong>Status:</strong> Available</p><p>A shared grocery-list app for households and groups. Its current scope includes multiple lists, item suggestions, quantities, per-item icons, editing, purchase recording, and direct list sharing with other users on the instance.</p><p>Shopper demonstrates how a focused collaborative app can reuse Sovereign identity, user selection, notifications, and app-scoped data.</p><p><a href="https://github.com/sovereignfs/sovereign-plugin-shopper" target="_blank" rel="noreferrer">Source: sovereign-plugin-shopper</a></p><h3 id="sovereign-tally" tabindex="-1">Sovereign Tally <a class="header-anchor" href="#sovereign-tally" aria-label="Permalink to &quot;Sovereign Tally&quot;">​</a></h3><p><strong>Status:</strong> Available</p><p>Splits shared expenses across a group — a household, a trip, a friend circle — and tracks who owes whom. Balances roll up across groups and simplify down to the fewest transfers that settle everyone, so the answer to &quot;what do I owe?&quot; is always current without anyone having to raise it.</p><p><a href="https://github.com/sovereignfs/sovereign-plugin-tally" target="_blank" rel="noreferrer">Source: sovereign-plugin-tally</a></p><h3 id="sovereign-tasks" tabindex="-1">Sovereign Tasks <a class="header-anchor" href="#sovereign-tasks" aria-label="Permalink to &quot;Sovereign Tasks&quot;">​</a></h3><p><strong>Status:</strong> Available</p><p>A privacy-first task manager for personal and shared work. Tasks supports lists, subtasks, notes, due dates, recurrence, favourites, filters, search, manual reordering, bulk actions, and a mobile interface designed around swipeable lists and bottom sheets.</p><p>Tasks uses the Sovereign account and instance database rather than requiring a separate task-service account or deployment.</p><p><a href="https://github.com/sovereignfs/sovereign-plugin-tasks" target="_blank" rel="noreferrer">Source: sovereign-plugin-tasks</a></p><h3 id="sovereign-travellog" tabindex="-1">Sovereign Travellog <a class="header-anchor" href="#sovereign-travellog" aria-label="Permalink to &quot;Sovereign Travellog&quot;">​</a></h3><p><strong>Status:</strong> Available</p><p>A private trip planner and personal place check-in log. Plan trips, record the places you have actually been, and keep that history on your own instance rather than in a third-party social network. Place search runs through a configurable Nominatim or Photon endpoint, which an operator can point at their own deployment to keep search queries off a public service entirely.</p><p><a href="https://github.com/sovereignfs/sovereign-plugin-travellog" target="_blank" rel="noreferrer">Source: sovereign-plugin-travellog</a></p><h3 id="sovereign-warden" tabindex="-1">Sovereign Warden <a class="header-anchor" href="#sovereign-warden" aria-label="Permalink to &quot;Sovereign Warden&quot;">​</a></h3><p><strong>Status:</strong> Available</p><p>A personal AI chat assistant built into the platform. Each user connects their own OpenAI-API-compatible provider — OpenRouter, a vendor directly, or a self-hosted server — with their own API key, and chats against it in multiple named, pinnable sessions. If the operator runs the optional local inference add-on, its model appears in the same picker with no key required.</p><p>Warden ships inside the platform repository rather than a standalone one, but it is an ordinary installable app rather than workspace chrome: on a new instance it stays inactive until an administrator enables it from Console, and it keeps its own isolated database.</p><p><a href="/plugins/warden.html">Specification: Warden</a></p><h3 id="sovereign-docs" tabindex="-1">Sovereign Docs <a class="header-anchor" href="#sovereign-docs" aria-label="Permalink to &quot;Sovereign Docs&quot;">​</a></h3><p><strong>Status:</strong> In development</p><p>A document workspace where documents are Markdown underneath — editable through either a Markdown or a WYSIWYG view, and exportable as plain <code>.md</code> at any time. Documents live in the app&#39;s own database by default, bounded by an operator-set limit. Connecting a Git repository is an opt-in second tier that lifts that limit and gives a browsable Markdown tree with commit history in a repo you own.</p><p><a href="https://github.com/sovereignfs/sovereign-plugin-docs" target="_blank" rel="noreferrer">Source: sovereign-plugin-docs</a></p><h3 id="sovereign-wallet" tabindex="-1">Sovereign Wallet <a class="header-anchor" href="#sovereign-wallet" aria-label="Permalink to &quot;Sovereign Wallet&quot;">​</a></h3><p><strong>Status:</strong> In development</p><p>A private wallet for loyalty and membership cards, sensitive-document snapshots, and personal financial records. The card flows — creating, listing, opening, and displaying QR or barcode-based cards — are the current focus.</p><p>Wallet is not yet presented as generally available, and the sensitive-document features beyond the card flows are not shipped. The encryption foundations they were waiting on do now exist: Wallet is one of only two apps — Account is the other — that use the platform&#39;s client-side encryption contract, so the card metadata and document images it does store cannot be decrypted by the server.</p><p><a href="https://github.com/sovereignfs/sovereign-plugin-wallet" target="_blank" rel="noreferrer">Source: sovereign-plugin-wallet</a></p><h2 id="core-workspace-apps" tabindex="-1">Core workspace apps <a class="header-anchor" href="#core-workspace-apps" aria-label="Permalink to &quot;Core workspace apps&quot;">​</a></h2><p>These platform apps provide the shared workspace itself. Unlike the apps above they are not installed or activated — they are the workspace.</p><table tabindex="0"><thead><tr><th>App</th><th>Availability</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Launcher</strong></td><td>Available</td><td>The workspace home screen and entry point to installed apps.</td></tr><tr><td><strong>Account</strong></td><td>Available</td><td>Profile, sign-in security, preferences, activity, and data controls.</td></tr><tr><td><strong>Inbox</strong></td><td>Available</td><td>Notifications, and durable messages from apps and administrators.</td></tr><tr><td><strong>Console</strong></td><td>Available to operators</td><td>User, app, instance, and system administration.</td></tr></tbody></table><p>Read the <a href="/plugins/launcher.html">Launcher</a>, <a href="/plugins/account.html">Account</a>, <a href="/plugins/inbox.html">Inbox</a>, and <a href="/plugins/console.html">Console</a> documentation.</p><h2 id="how-these-appear-in-the-repository" tabindex="-1">How these appear in the repository <a class="header-anchor" href="#how-these-appear-in-the-repository" aria-label="Permalink to &quot;How these appear in the repository&quot;">​</a></h2><p>The platform repository commits only the apps that ship inside it. Every other app arrives in a checkout at install time, and <code>.gitignore</code> enforces that split: <code>/plugins/*/</code> is ignored with an explicit allowlist for the five directories below, so an installed app stays owned by its own repository instead of being vendored into the platform&#39;s history.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/</span></span>
<span class="line"><span>├── account/                  committed — platform app</span></span>
<span class="line"><span>├── console/                  committed — platform app</span></span>
<span class="line"><span>├── inbox/                    committed — platform app</span></span>
<span class="line"><span>├── launcher/                 committed — platform app</span></span>
<span class="line"><span>├── warden/                   committed — first-party app, built in</span></span>
<span class="line"><span>└── &lt;installed app&gt;/          cloned at install time, never committed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>example-plugins/              committed — developer references, not products</span></span>
<span class="line"><span>├── example-basic/            example-layouts/</span></span>
<span class="line"><span>├── example-api/              example-mobile/</span></span>
<span class="line"><span>├── example-minimal/          example-mobile-poc/</span></span>
<span class="line"><span>├── example-monetized/        example-encrypted/</span></span>
<span class="line"><span>├── example-overlay-small/    example-device-only/</span></span>
<span class="line"><span>├── example-overlay-medium/</span></span>
<span class="line"><span>└── example-overlay-large/</span></span></code></pre></div><p>Which apps an instance installs is an operator decision rather than a property of the platform, so it is declared per checkout: <code>scripts/install-plugins.ts</code> reads a <code>sovereign.plugins.json</code> at the repository root — a local, gitignored file — and clones each declared repository and reference into <code>plugins/&lt;id&gt;/</code>. When that file is absent the committed <code>sovereign.plugins.default.json</code> applies instead, and it is deliberately empty: a fresh clone runs the platform apps and nothing else. An operator copies it to <code>sovereign.plugins.json</code> to declare a larger set.</p><p>A developer may use a <code>.local</code> suffix for an editable local checkout, but that suffix is not part of the canonical app or plugin name. The standalone app repository remains authoritative for its manifest, implementation, and release history.</p><p>Example plugins are developer references rather than products meant for normal workspace use. They live in <code>example-plugins/</code> rather than <code>plugins/</code>, and are composed into a build only when <code>SOVEREIGN_EXAMPLES_ENABLED</code> is set.</p><h2 id="build-for-a-custom-need" tabindex="-1">Build for a custom need <a class="header-anchor" href="#build-for-a-custom-need" aria-label="Permalink to &quot;Build for a custom need&quot;">​</a></h2><p>An app is delivered to Sovereign as a plugin. Instead of creating a separate service stack, a developer can use the runtime&#39;s supported contracts for:</p><ul><li>Authentication and the current user session.</li><li>App-scoped database access.</li><li>Shared interface components and workspace navigation.</li><li>Declared storage, notification, job, event, and integration capabilities as those contracts become available.</li><li>Operator-managed installation and access.</li></ul><p><a href="/get-started/developers.html">Start building an app</a></p>`,67)])])}const u=a(s,[["render",o]]);export{g as __pageData,u as default};
